+// formatDuration formats d with a fixed number of decimals and a unit
+// suffix padded to a consistent width so decimal points align in the
+// metrics table columns.
+func formatDuration(d time.Duration) string {
+	var value float64
+	var unit string
+	switch {
+	case d < time.Microsecond:
+		value, unit = float64(d.Nanoseconds()), "ns"
+	case d < time.Millisecond:
+		value, unit = float64(d.Nanoseconds())/1e3, "µs"
+	case d < time.Second:
+		value, unit = float64(d.Nanoseconds())/1e6, "ms"
+	default:
+		value, unit = d.Seconds(), "s"
+	}
+	return fmt.Sprintf("%.2f%-2s", value, unit)
+}
