+// Fingerprint returns the Subresource Integrity (SRI) hash (e.g. "sha256-b3f...")
+// of the content read from r using the given algorithm. If algo is empty, the
+// default algorithm (sha256) is used.
+func Fingerprint(r io.Reader, algo string) (string, error) {
+	if algo == "" {
+		algo = defaultHashAlgo
+	}
+	h, err := newHash(algo)
+	if err != nil {
+		return "", err
+	}
+	if _, err := io.Copy(h, r); err != nil {
+		return "", err
+	}
+	return integrity(algo, h.Sum(nil)), nil
+}
+
 func integrity(algo string, sum []byte) string {
 	encoded := base64.StdEncoding.EncodeToString(sum)
 	return algo + "-" + encoded
