+// md5, sha256, sha384 or sha512.
+func (ns *Namespace) Fingerprint(ctx context.Context, args ...any) (string, error) {
+	if len(args) < 1 {
+		return "", errors.New("must provide a value")
+	}
+
+	if len(args) > 2 {
+		return "", errors.New("must not provide more than a value and a hash algorithm")
