+		if err != nil {
+			return "", err
+		}
+		conv, err = cast.ToStringE(c)
+	} else {
+		conv, err = cast.ToStringE(args[valIdx])
+	}
+	if err != nil {
+		return "", err
+	}
+
+	return integrity.Fingerprint(strings.NewReader(conv), algo)
